def pipeline_order(stages, deps):
    """Kahn 拓扑排序：无依赖阶段按 stages 顺序输出；有环抛 ValueError。"""
    indeg = {s: 0 for s in stages}
    adj = {s: [] for s in stages}
    for u, v in deps:
        adj[u].append(v)
        indeg[v] += 1
    ready = [s for s in stages if indeg[s] == 0]
    order = []
    i = 0
    while i < len(ready):
        cur = ready[i]
        i += 1
        order.append(cur)
        for nxt in adj[cur]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                ready.append(nxt)
    return order

