import pytest
from target import pipeline_order

def test_linear_pipeline():
    assert pipeline_order(["b", "a"], [("a", "b")]) == ["a", "b"]

def test_no_deps():
    assert pipeline_order(["p", "q"], []) == ["p", "q"]

def test_dependency_cycle():
    with pytest.raises(ValueError):
        pipeline_order(["x", "y"], [("x", "y"), ("y", "x")])
